#!/usr/bin/env python3
"""Database migration script for MongoDB user analytics collection.
Migrates legacy user records to new schema with computed fields.
Runs as a Kubernetes CronJob for scheduled maintenance windows.
"""

import os
import sys
import json
import logging
from datetime import datetime
from pymongo import MongoClient

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger('migration')

MONGO_URI = os.environ.get('MONGO_URI', 'mongodb://localhost:27017')
DB_NAME = os.environ.get('DB_NAME', 'analytics')
MIGRATION_BATCH_SIZE = int(os.environ.get('BATCH_SIZE', '500'))
FILTER_CONFIG_PATH = os.environ.get('FILTER_CONFIG', '/etc/migration/filter.json')


def load_filter_config():
    """Load migration filter from config file or environment override."""
    config_source = os.environ.get('FILTER_OVERRIDE')
    if config_source:
        try:
            return json.loads(config_source)
        except json.JSONDecodeError:
            logger.warning("Invalid FILTER_OVERRIDE JSON, falling back to file")

    try:
        with open(FILTER_CONFIG_PATH, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logger.info("No filter config found, using default")
        return {"status": "active"}


def build_migration_query(filter_config):
    """Build MongoDB query from filter configuration.
    Supports nested operators for complex migration selections.
    """
    query = {}
    for key, value in filter_config.items():
        if key.startswith('$'):
            # Allow MongoDB operators directly for flexible filtering
            query[key] = value
        elif isinstance(value, dict):
            query[key] = value
        else:
            query[key] = value
    return query


def compute_derived_fields(record):
    """Compute new schema fields from legacy record."""
    derived = {
        'full_name': f"{record.get('first_name', '')} {record.get('last_name', '')}".strip(),
        'migrated_at': datetime.utcnow(),
        'schema_version': 2,
        'legacy_id': str(record.get('_id', '')),
    }
    if 'login_history' in record:
        derived['total_logins'] = len(record['login_history'])
        derived['last_login'] = record['login_history'][-1] if record['login_history'] else None
    return derived


def run_migration():
    """Execute the migration in batches."""
    client = MongoClient(MONGO_URI, serverSelectionTimeoutMS=5000)
    db = client[DB_NAME]

    source_collection = db['users_legacy']
    target_collection = db['users_v2']

    filter_config = load_filter_config()
    query = build_migration_query(filter_config)

    logger.info(f"Starting migration with query: {json.dumps(query, default=str)}")

    total_migrated = 0
    cursor = source_collection.find(query).batch_size(MIGRATION_BATCH_SIZE)

    batch = []
    for record in cursor:
        derived = compute_derived_fields(record)
        new_record = {**record, **derived}
        del new_record['_id']  # Let MongoDB assign new _id
        batch.append(new_record)

        if len(batch) >= MIGRATION_BATCH_SIZE:
            target_collection.insert_many(batch)
            total_migrated += len(batch)
            logger.info(f"Migrated batch: {total_migrated} records total")
            batch = []

    if batch:
        target_collection.insert_many(batch)
        total_migrated += len(batch)

    logger.info(f"Migration complete: {total_migrated} records migrated")

    # Write migration status to shared volume for monitoring
    status_path = os.environ.get('STATUS_PATH', '/var/run/migration/status.json')
    os.makedirs(os.path.dirname(status_path), exist_ok=True)
    with open(status_path, 'w') as f:
        json.dump({
            'completed_at': datetime.utcnow().isoformat(),
            'records_migrated': total_migrated,
            'query_used': json.dumps(query, default=str)
        }, f)

    return total_migrated


if __name__ == '__main__':
    try:
        count = run_migration()
        sys.exit(0)
    except Exception as e:
        logger.error(f"Migration failed: {e}")
        sys.exit(1)
